using System.Text.Json;
using MusicGen.Core.Weights;
using TorchSharp;
using static TorchSharp.torch;

namespace HeartMuLa.Tests;

/// <summary>
/// Checks that the fixtures generated by tools/dump_reference.py (Python) can be read with the C# reader
/// and have the keys, dtypes and shapes the parity tests will use. Needs no checkpoint.
/// </summary>
public class FixturesTests
{
    private static readonly string Dir = Fixtures.Dir;

    private static Dictionary<string, (string dtype, long[] shape)> Describe(string file) =>
        SafeTensors.Describe(Path.Combine(Dir, file)).ToDictionary(x => x.name, x => (x.dtype, x.shape));

    private static void Expect(Dictionary<string, (string dtype, long[] shape)> got, string key, string dtype, params long[] shape)
    {
        Assert.True(got.ContainsKey(key), $"missing key '{key}'");
        Assert.Equal(dtype, got[key].dtype);
        // -1 in the expected shape = any size
        Assert.Equal(shape.Length, got[key].shape.Length);
        for (int i = 0; i < shape.Length; i++)
            if (shape[i] >= 0) Assert.Equal(shape[i], got[key].shape[i]);
    }

    [Fact]
    public void Reference_HasPromptAndFirstFrameTensors()
    {
        var d = Describe("reference.safetensors");
        Expect(d, "tokens", "I64", 2, -1, 9);
        Expect(d, "tokens_mask", "BOOL", 2, -1, 9);
        Expect(d, "pos", "I64", 2, -1);
        Expect(d, "muq_embed", "F32", 2, 512);
        Expect(d, "muq_idx", "I64");
        Expect(d, "cfg_scale", "F32");
        Expect(d, "last_h", "F32", 2, 3072);
        Expect(d, "c0_logits", "F32", 2, 8197);
        Assert.Equal(d["tokens"].shape[1], d["pos"].shape[1]);
    }

    [Fact]
    public void Reference_LoadsWithFiniteValues()
    {
        var r = SafeTensors.LoadFile(Path.Combine(Dir, "reference.safetensors"));
        Assert.Equal(ScalarType.Int64, r["tokens"].dtype);
        Assert.Equal(ScalarType.Bool, r["tokens_mask"].dtype);
        Assert.True(r["last_h"].isfinite().all().item<bool>());
        Assert.True(r["c0_logits"].isfinite().all().item<bool>());
    }

    [Fact]
    public void Rope_HasInputsOutputsAndParams()
    {
        var d = Describe("rope.safetensors");
        Expect(d, "x", "F32", 2, 16, 4, 128);
        Expect(d, "out_small", "F32", 2, 16, 4, 128);
        Expect(d, "out_large", "F32", 2, 16, 4, 128);
        Expect(d, "x_bf16", "BF16", 2, 16, 4, 128);
        Expect(d, "out_bf16", "BF16", 2, 16, 4, 128);
        Expect(d, "pos_small", "I64", 2, 16);
        Expect(d, "pos_large", "I64", 2, 16);
        Expect(d, "theta", "F32", 64);
        Expect(d, "params", "F32", 7);

        var p = SafeTensors.LoadFile(Path.Combine(Dir, "rope.safetensors"))["params"].data<float>().ToArray();
        Assert.Equal(new float[] { 128, 500000, 8192, 32, 1, 4, 8192 }, p);
    }

    [Fact]
    public void PromptIds_AreNonEmptyIdLists()
    {
        var table = JsonSerializer.Deserialize<Dictionary<string, long[]>>(File.ReadAllText(Path.Combine(Dir, "prompt_ids.json")))!;
        Assert.Equal(2, table.Count);
        Assert.All(table.Values, ids => Assert.NotEmpty(ids));
    }

    [Fact]
    public void TokenizerCases_CoverNonAsciiAndStartWithBos()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(Dir, "tokenizer_cases.json")));
        var cases = doc.RootElement.GetProperty("cases").EnumerateArray().ToList();
        var names = cases.Select(c => c.GetProperty("name").GetString()).ToHashSet();
        foreach (var n in new[] { "spanish_ene", "accents", "cjk_chinese", "cjk_japanese", "tag_wrapped" })
            Assert.Contains(n, names);
        Assert.All(cases, c => Assert.Equal(128000, c.GetProperty("ids")[0].GetInt64())); // BOS is added by the tokenizer
    }

    [Fact]
    public void Frames_AndLogits_AreConsistent()
    {
        var f = Describe("frames_py.safetensors");
        Expect(f, "frames", "I64", 8, -1);
        long t = f["frames"].shape[1];

        var l = Describe("frames_logits.safetensors");
        Expect(l, "c0_logits", "F32", -1, 2, 8197);
        Expect(l, "last_h", "F32", -1, 2, 3072);
        Assert.Contains(l["c0_logits"].shape[0], new[] { t, t + 1 }); // +1 if it ended by EOS
    }

    [Fact]
    public void CodecFixtures_HaveNoiseLatentsAndStereoWav()
    {
        var f = Describe("frames_py.safetensors");
        long t = f["frames"].shape[1];

        var lat = Describe("codec_latents.safetensors");
        Expect(lat, "frames", "I64", 8, t);
        Assert.Contains(lat.Keys, k => k.StartsWith("randn_"));
        Expect(lat, "codes_seg0", "I64", 1, 8, 372);   // repeated up to a 29.76 s window
        Expect(lat, "latents_seg0", "F32", 1, 744, 256);
        Assert.Contains("decode_in_seg0", lat.Keys);

        var w = Describe("codec_wav.safetensors");
        Expect(w, "wav", "F32", 2, (long)(t / 12.5 * 48000));
    }

    [Fact]
    public void LongCodecFixtures_HaveTwoWindowsWithTheFourNoiseTensors()
    {
        var lat = Describe("codec_long_latents.safetensors");
        Expect(lat, "frames", "I64", 8, 400);
        Expect(lat, "codes_seg0", "I64", 1, 8, 372);
        Expect(lat, "codes_seg1", "I64", 1, 8, 372);
        Expect(lat, "randn_0_detokenize", "F32", 1, 744, 256);        // first_latent (masked to zero in window 0)
        Expect(lat, "randn_1_inference_codes", "F32", 1, 744, 256);   // flow-matching noise of window 0
        Expect(lat, "randn_2_detokenize", "F32", 1, 640, 256);        // padding of the in-context latents of window 1
        Expect(lat, "randn_3_inference_codes", "F32", 1, 744, 256);   // flow-matching noise of window 1
        Expect(lat, "latents_seg0", "F32", 1, 744, 256);
        Expect(lat, "latents_seg1", "F32", 1, 744, 256);
        Expect(lat, "decode_in_seg0", "F32", 2, 128, 744);
        Expect(lat, "decode_in_seg1", "F32", 2, 128, 744);

        var w = Describe("codec_long_wav.safetensors");
        Expect(w, "wav", "F32", 2, 1_536_000);                          // int(400 / 12.5 * 48000)
    }
}
